mapper.select:
SELECT ct.cash_transaction_id, ct.account_id, ct.transaction_type, ct.amount, ct.balance_after, ct.memo, ct.transaction_at FROM cash_transaction ct
ct.account_id = #{accountId}
AND ct.transaction_at >= #{from}
AND ct.transaction_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
ORDER BY ct.transaction_at DESC

SELECT COALESCE(SUM(CASE WHEN ct.transaction_type = 'DEPOSIT' THEN ct.amount ELSE -ct.amount END), 0)
FROM cash_transaction ct
JOIN account_link al ON al.account_id = ct.account_id

    al.member_id = #{memberId}

        AND ct.transaction_at >= #{since}
